1	import { all, get, run } from '../db/index.js';
2	
3	export interface Book {
4	  id: number;
5	  title: string;
6	  author: string;
7	  isbn: string | null;
8	  cover_url: string | null;
9	  description: string | null;
10	  published_year: number | null;
11	  created_at: string;
12	}
13	
14	export function getAllBooks(): Book[] {
15	  return all('SELECT * FROM books ORDER BY title') as unknown as Book[];
16	}
17	
18	export function getBookById(id: number): Book | undefined {
19	  return get('SELECT * FROM books WHERE id = ?', [id]) as unknown as Book | undefined;
20	}
21	
22	export class SearchValidationError extends Error {}
23	
24	export function searchBooks(query: string): Book[] {
25	  const trimmed = typeof query === 'string' ? query.trim() : '';
26	
27	  if (trimmed.length > 100) {
28	    throw new SearchValidationError('Search query must be 100 characters or fewer');
29	  }
30	
31	  if (trimmed.length === 0) {
32	    return getAllBooks();
33	  }
34	
35	  const escaped = trimmed.replace(/[\\%_]/g, (ch) => `\\${ch}`);
36	  const pattern = `%${escaped}%`;
37	
38	  return all(
39	    "SELECT * FROM books WHERE title LIKE ? ESCAPE '\\' OR author LIKE ? ESCAPE '\\' ORDER BY title",
40	    [pattern, pattern]
41	  ) as unknown as Book[];
42	}
43	
44	export function createBook(data: Omit<Book, 'id' | 'created_at'>): Book {
45	  const result = run(
46	    'INSERT INTO books (title, author, isbn, cover_url, description, published_year) VALUES (?, ?, ?, ?, ?, ?)',
47	    [data.title, data.author, data.isbn, data.cover_url, data.description, data.published_year]
48	  );
49	  return getBookById(result.lastInsertRowid)!;
50	}
51	
52	export function updateBook(id: number, data: Partial<Omit<Book, 'id' | 'created_at'>>): Book | undefined {
53	  const existing = getBookById(id);
54	  if (!existing) return undefined;
55	
56	  const updates: string[] = [];
57	  const values: unknown[] = [];
58	
59	  if (data.title !== undefined) {
60	    updates.push('title = ?');
61	    values.push(data.title);
62	  }
63	  if (data.author !== undefined) {
64	    updates.push('author = ?');
65	    values.push(data.author);
66	  }
67	  if (data.isbn !== undefined) {
68	    updates.push('isbn = ?');
69	    values.push(data.isbn);
70	  }
71	  if (data.cover_url !== undefined) {
72	    updates.push('cover_url = ?');
73	    values.push(data.cover_url);
74	  }
75	  if (data.description !== undefined) {
76	    updates.push('description = ?');
77	    values.push(data.description);
78	  }
79	  if (data.published_year !== undefined) {
80	    updates.push('published_year = ?');
81	    values.push(data.published_year);
82	  }
83	
84	  if (updates.length === 0) return existing;
85	
86	  values.push(id);
87	  run(`UPDATE books SET ${updates.join(', ')} WHERE id = ?`, values);
88	  return getBookById(id);
89	}
90	
91	export function deleteBook(id: number): boolean {
92	  const result = run('DELETE FROM books WHERE id = ?', [id]);
93	  return result.changes > 0;
94	}
